     values ('custom-t-shirt', 'Cotton T-Shirt', (select id from categories where slug = 'apparel'), 'Combed cotton round-collar tee — chest logo up to 8 × 8 cm, back up to 10 × 25 cm.', 'Our most-ordered garment. A mid-weight combed cotton round-collar tee that holds its shape through wash after wash, printed with the method that suits your artwork — screen for bold spot colour, DTF for photographic detail. Cotton takes a placed print: a logo up to 8 × 8 cm on the left or right chest and a back print up to 10 × 25 cm. For an all-over design, choose the sports-fabric T-shirt.', '{"materials":["100% combed cotton, 180 gsm","Cotton/poly blend, 160 gsm"],"fabric":"cotton","sizes":["XS","S","M","L","XL","2XL","3XL","4XL","5XL","6XL","7XL","8XL"],"colours":[{"name":"White","hex":"#f5f5f2"},{"name":"Black","hex":"#17171a"},{"name":"Navy","hex":"#1b2447"},{"name":"Royal","hex":"#2a35d6"},{"name":"Sky","hex":"#4db4e8"},{"name":"Red","hex":"#d4302b"},{"name":"Forest","hex":"#1f5a3d"},{"name":"Yellow","hex":"#ffd60a"},{"name":"Orange","hex":"#f2711c"},{"name":"Heather","hex":"#9a9da3"},{"name":"Sand","hex":"#d8cbb0"},{"name":"Maroon","hex":"#6b1f2a"}],"printMethods":["screen","dtf"],"customisation":["Left or right chest logo (up to 8 × 8 cm)","Back print (up to 10 × 25 cm)","Sleeve print","Neck label","Individual names & numbers","Pantone-matched ink"],"useCases":["Events & festivals","Staff uniforms","School & university","Merchandise","Campaign giveaways"],"studio":{"garment":"tee","areas":[{"key":"left-chest","label":"Left chest","widthMm":80,"heightMm":80},{"key":"right-chest","label":"Right chest","widthMm":80,"heightMm":80},{"key":"back","label":"Back","widthMm":100,"heightMm":250},{"key":"left-sleeve","label":"Left sleeve","widthMm":90,"heightMm":90},{"key":"right-sleeve","label":"Right sleeve","widthMm":90,"heightMm":90}]},"seo":{"title":"Cotton T-Shirt Printing in Laos","description":"Design your own cotton T-shirt online — chest logo, back print and sleeves in sizes